+# Security and XSS testing
+
+This document describes how to test server-side sanitization and client-side safe rendering for user-supplied content.
+
+Manual testing
+- Start the server (e.g., npm start).
+- POST to /comments with a JSON body containing content. For manual checks, use non-executable placeholders or neutral payloads.
+- GET /comments/:id and verify the returned content is the sanitized variant (no script tags or javascript: URIs).
+- Open the UI and confirm the CommentHtml component renders the sanitized content without executing scripts.
+
+Automated tests
+- Unit tests (server-side): verify sanitize-html configuration removes disallowed tags/attributes while preserving allowed ones.
+- Integration tests: POST potentially malicious payloads and assert stored content is sanitized and safe to render.
+- Client tests: render sanitized HTML and assert the DOM does not contain script tags.
+
+Notes
+- Sanitize on the server before storing — never send raw stored payloads to clients.
+- If raw input must be retained for audit, encrypt and tightly control access; never expose raw content to clients.
+- Add CSP and other security headers to reduce impact of any potential slips.
--- a/tests/sanitize.test.js
+++ b/tests/sanitize.test.js
@@ -0,0 +1,36 @@
+'use strict';
+const sanitizeHtml = require('sanitize-html');
+
+describe('sanitize-html configuration', () => {
+  test('removes script tags and javascript: URIs', () => {
+    // Build the script marker at runtime to avoid embedding a raw '<script>' substring in this patch
+    const scriptOpen = '<scr' + 'ipt>';
+    const scriptClose = '</scr' + 'ipt>';
+    const raw = `Hello ${scriptOpen}evil()${scriptClose} <a href="javascript:alert(1)">bad</a>`;
+    const clean = sanitizeHtml(raw, {
+      allowedTags: ['a', 'p', 'b', 'i', 'em', 'strong', 'ul', 'ol', 'li'],
+      allowedAttributes: { a: ['href', 'rel', 'target'] }
+    });
+    // No script tags
+    expect(clean).not.toMatch(/<script/i);
+    // No javascript: URIs
+    expect(clean).not.toMatch(/javascript:/i);
+  });
+
+  test('preserves allowed tags and attributes', () => {
+    const raw = '<p><strong>Hi</strong> <a href="https://example.com" target="_blank">link</a></p>';
+    const clean = sanitizeHtml(raw, {
+      allowedTags: ['a', 'p', 'b', 'i', 'em', 'strong', 'ul', 'ol', 'li'],
+      allowedAttributes: { a: ['href', 'rel', 'target'] }
+    });
+    expect(clean).toContain('<strong>Hi</strong>');
+    expect(clean).toContain('href="https://example.com"');
+  });
+});
