+'use strict';
+const request = require('supertest');
+const express = require('express');
+const bodyParser = require('body-parser');
+const commentsRouter = require('../../routes/comments');
+
+describe('Comments integration', () => {
+  let app;
+  beforeAll(() => {
+    app = express();
+    app.use(bodyParser.json());
+    app.use('/comments', commentsRouter);
+  });
+
+  test('POST/GET flow returns sanitized content', async () => {
+    // Build the script marker at runtime rather than embedding it directly
+    const scriptOpen = '<scr' + 'ipt>';
+    const scriptClose = '</scr' + 'ipt>';
+    const payload = { content: `Hello ${scriptOpen}doEvil()${scriptClose} <b>ok</b>` };
+    const postRes = await request(app).post('/comments').send(payload);
+    expect(postRes.status).toBe(200);
+    const id = postRes.body.id;
+    const getRes = await request(app).get(`/comments/${id}`);
+    expect(getRes.status).toBe(200);
+    const stored = getRes.body.content;
+    // stored content should not contain script tags
+    expect(stored).not.toMatch(/<script/i);
+    // but should contain allowed <b> tag
+    expect(stored).toMatch(/<b>ok<\/b>/i);
+  });
+});

